input.command:
$path = "evidence\10A_GAN_WBG_SOURCES.csv"
$rows = Import-Csv $path
"Row count: $($rows.Count)"
"Column count: $($rows[0].psobject.Properties.Name.Count)"
"Columns: $($rows[0].psobject.Properties.Name -join ', ')"
$badTier = $rows | Where-Object { $_.quality_tier -notin @('A','B','C') }
"Rows with invalid quality_tier: $($badTier.Count)"
$badAccess = $rows | Where-Object { $_.access_level -notin @('full_text','abstract_metadata','metadata_only') }
"Rows with invalid access_level: $($badAccess.Count)"
$badPRS = $rows | Where-Object { $_.peer_review_status -ne 'verified_peer_reviewed' }
"Rows with non-standard peer_review_status: $($badPRS.Count)"
$emptyDoi = $rows | Where-Object { -not $_.doi -or -not $_.url -or -not $_.title }
"Rows missing doi/url/title: $($emptyDoi.Count)"
$dupIds = $rows | Group-Object source_id | Where-Object { $_.Count -gt 1 }
"Duplicate source_id groups: $($dupIds.Count)"
$dupDoi = $rows | Group-Object doi | Where-Object { $_.Count -gt 1 }
"Duplicate DOI groups: $($dupDoi.Count)"
$rows | Group-Object source_type | Select-Object Name, Count

$rows = Import-Csv "evidence\10A_GAN_WBG_SOURCES.csv"
"--- Year distribution ---"
$rows | Group-Object year | Sort-Object Name | ForEach-Object { "$($_.Name): $($_.Count)" }
"--- Decade buckets ---"
$rows | ForEach-Object { [int]([int]$_.year - ([int]$_.year % 10)) } | Group-Object | Sort-Object Name | ForEach-Object { "$($_.Name)s: $($_.Count)" }
"--- Venue distribution (top) ---"
$rows | Group-Object venue | Sort-Object Count -Descending | ForEach-Object { "$($_.Name): $($_.Count)" }
"--- Quality tier ---"
$rows | Group-Object quality_tier | Sort-Object Name | ForEach-Object { "$($_.Name): $($_.Count)" }
"--- Access level ---"
$rows | Group-Object access_level | ForEach-Object { "$($_.Name): $($_.Count)" }
"--- Source type ---"
$rows | Group-Object source_type | ForEach-Object { "$($_.Name): $($_.Count)" }
